refentry.refsect1:
  &reftitle.parameters;




     expression


output गरिने expression। the strict_types directive सक्षम (enabled) भए तापनि Non-string values लाई strings मा coerce गरिनेछ।

  &reftitle.examples;



    print का उदाहरणहरू


<?php
print "print does not require parentheses.";
print PHP_EOL;

// No newline or space is added; the below outputs "helloworld" all on one line
print "hello";
print "world";
print PHP_EOL;

print "This string spans
multiple lines. The newlines will be
output as well";
print PHP_EOL;

print "This string spans\nmultiple lines. The newlines will be\noutput as well.";
print PHP_EOL;

// The argument can be any expression which produces a string
$foo = "example";
print "foo is $foo"; // foo is example
print PHP_EOL;

$fruits = ["lemon", "orange", "banana"];
print implode(" and ", $fruits); // lemon and orange and banana
print PHP_EOL;

// Non-string expressions are coerced to string, even if declare(strict_types=1) is used
print 6 * 7; // 42
print PHP_EOL;

// Because print has a return value, it can be used in expressions
// The following outputs "hello world"
if ( print "hello" ) {
    echo " world";
}
print PHP_EOL;

// The following outputs "true"
( 1 === 1 ) ? print 'true' : print 'false';
print PHP_EOL;
?>

  &reftitle.notes;


   parentheses सँगको प्रयोग

print को argument लाई parentheses ले घेर्दा कुनै syntax error आउँदैन, र यसले सामान्य function call जस्तै देखिने syntax उत्पन्न गर्दछ। तर, यो भ्रामक हुन सक्छ, किनभने ती parentheses वास्तवमा output गरिने expression को भाग हुन्, print syntax आफैँको भाग होइनन्।


<?php
print "hello";
// outputs "hello"

print("hello");
// also outputs "hello", because ("hello") is a valid expression

print(1 + 2) * 3;
// outputs "9"; the parentheses cause 1+2 to be evaluated first, then 3*3
// the print statement sees the whole expression as one argument

if ( print("hello") && false ) {
    print " - inside if";
}
else {
    print " - inside else";
}
// outputs " - inside if"
// the expression ("hello") && false is first evaluated, giving false
// this is coerced to the empty string "" and printed
// the print construct then returns 1, so code in the if block is run
?>






एउटा ठूलो expression मा print प्रयोग गर्दा, अपेक्षित नतिजा प्राप्त गर्नका लागि keyword र यसको argument दुवैलाई parentheses भित्र राख्नु आवश्यक हुन सक्छ:


<?php
if ( (print "hello") && false ) {
    print " - inside if";
}
else {
    print " - inside else";
}
// outputs "hello - inside else"
// unlike the previous example, the expression (print "hello") is evaluated first
// after outputting "hello", print returns 1
// since 1 && false is false, code in the else block is run

print "hello " && print "world";
// outputs "world1"; print "world" is evaluated first,
// then the expression "hello " && 1 is passed to the left-hand print

(print "hello ") && (print "world");
// outputs "hello world"; the parentheses force the print expressions
// to be evaluated before the &&
?>






  &note.language-construct;
